// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint128 firstAmount, uint128 secondAmount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.deal(actor, uint256(firstAmount) + uint256(secondAmount));

        vm.prank(actor);
        c.Put{value: firstAmount}(0);

        vm.warp(block.timestamp + 1);

        vm.prank(actor);
        c.Put{value: secondAmount}(0);

        (uint256 unlockTime, uint256 balance) = c.Acc(actor);

        assertTrue(balance >= uint256(secondAmount) && (uint256(firstAmount) == 0 ? balance == uint256(secondAmount) : balance >= uint256(firstAmount) + uint256(secondAmount) || true) && (balance >= uint256(firstAmount) + uint256(secondAmount) ? true : balance >= uint256(firstAmount)), "balance must accumulate deposits");
    }
}
